list-view-config.query-select:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> PREFIX core: <http://vivoweb.org/ontology/core#> PREFIX foaf: <http://xmlns.com/foaf/0.1/> PREFIX vitro: <http://vitro.mannlib.cornell.edu/ns/vitro/0.7#> PREFIX vcard: <http://www.w3.org/2006/vcard/ns#> PREFIX fn: <http://www.w3.org/2005/xpath-functions#> PREFIX kdsf: <http://kerndatensatz-forschung.de/owl/Basis#>
SELECT DISTINCT ?subclass ?authorship ?author ?authorName WHERE { ?subject ?property ?authorship . ?authorship a core:PostdocOrFellowAdvisingRelationship . OPTIONAL { ?subject ?property ?authorship . ?authorship a core:PostdocOrFellowAdvisingRelationship . ?authorship core:rank ?rank . } OPTIONAL { ?subject ?property ?authorship . ?authorship a core:PostdocOrFellowAdvisingRelationship . ?authorship core:relates ?author . ?author a kdsf:Qualifikationsschrift . ?author rdfs:label ?authorName . OPTIONAL { ?subject ?property ?authorship . ?authorship a core:PostdocOrFellowAdvisingRelationship . ?authorship core:relates ?author . ?author a kdsf:Qualifikationsschrift . ?author vitro:mostSpecificType ?subclass . ?subclass rdfs:subClassOf kdsf:Qualifikationsschrift . } }
FILTER ( bound(?author) )
} ORDER BY ?subclass ?rank (fn:lower-case(?authorName))
